export const FONT_ASSET_SOURCES = {
  spaceGrotesk: {
    filename: "space-grotesk-latin.woff2",
    bodyBase64: SPACE_GROTESK_WOFF2_BASE64,
    contentType: "font/woff2",
  },
  newsreader: {
    filename: "newsreader-latin.woff2",
    bodyBase64: NEWSREADER_WOFF2_BASE64,
    contentType: "font/woff2",
  },
} as const satisfies Record<string, FontAssetSource>;

export type FontAssetKey = keyof typeof FONT_ASSET_SOURCES;

export const fontAssetPath = (key: FontAssetKey): string => {
  const asset = FONT_ASSET_SOURCES[key];
  return `${FONT_ASSET_BASE_PATH}/${asset.filename}`;
};

export const FONT_FACE_CSS = `
@font-face {
  font-family: "Space Grotesk";
  src: url("${fontAssetPath("spaceGrotesk")}") format("woff2");
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
}

@font-face {
  font-family: "Newsreader";
  src: url("${fontAssetPath("newsreader")}") format("woff2");
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
}
`;

export const decodeFontAssetBody = (bodyBase64: string): Uint8Array => {
  const binary = atob(bodyBase64);
  const bytes = new Uint8Array(binary.length);

  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }

  return bytes;
};
